import json,html
from september_ict_report import render_tables
d=json.load(open('.local/reports/plm-september-analysis-2026-10-01.json'))
ict=json.load(open('.local/reports/plm-september-ict-tradeoffs-2026-10-01.json'))
e=lambda x:html.escape(str(x))
def pc(x):return '—' if x is None else f'{x*100:.1f}%'.replace('.',',')
def tbl(h,rows):
    return '<div class="scroll"><table><thead><tr>'+''.join(f'<th>{e(x)}</th>' for x in h)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{e(c)}</td>' for c in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def cutrows(v):return [[c['name'],f"{c['removed']}/96",f"{c['strong_removed']}/{c['strong_total']}",f"{c['strong_kept']}/{c['strong_total']}",f"{c['stops_removed']}/{c['stops_total']}",f"{c['bu_removed']}/{c['bu_total']}",f"{c['censored_removed']}/{c['censored_total']}",c['unknown']] for c in v]
CH=['Условие, которое сохраняет вход','Убрано входов','Потеряно сильных (72h ≥10%)','Сохранено сильных','Убрано STOP LOSS','Убрано БУ','Убрано неполных окон','Неизвестно (сохранено)']
b=d['base'];cl=d['cls']
bandrows=lambda k:[[x['label'],x['n'],f"{x['strong']}/{x['complete']}",pc(x['strong_rate']),x['stops'],x['bu'],x['censored']] for x in d['bands'][k]]
BH=['Диапазон','Входов','Сильных 72h / полных окон','Доля','STOP LOSS','БУ','Неполных окон']
names={'sv':'Spot volume на входе','p3':'Рост за 3 часа','p24':'Рост за 24 часа','cvdn':'Число положительных CVD таймфреймов','ft':'Futures Taker net-buy'}
WK=', '.join(k+': '+pc(v['strong_rate'])+' ('+str(v['strong'])+'/'+str(v['complete'])+'), стопов '+str(v['stops']) for k,v in d['weeks'].items())
band_html=''.join(f'<h3>{names[k]}</h3>'+tbl(BH,bandrows(k)) for k in ['sv','p24','p3','cvdn','ft'])
pcl=d['postclose']
sec=lambda i,t,c:f'<section id="{i}"><h2>{e(t)}</h2>{c}</section>'
g=lambda k:cl[k]
body=''.join([
sec('answer','Итог по всему сентябрю',f"""<p>Выборка: <strong>96 входов PLM</strong> за сентябрь по Asia/Dubai, без разделения на старые и новые правила входа. Первичный критерий — пик ≥10% за полные 72 часа после входа: <strong>45 из 91</strong> полных окон (49,5%). Ещё 5 окон не завершены. Записанный пик внутри позиции ≥10% был у 34 из 96. Stop loss — 19, БУ — 37, profit — 26, expired — 9, активных — 5.</p>
<p><strong>Нового фильтра, который убирает стопы и не теряет заметную часть сильных движений, не найдено.</strong> Сильнее всего различает исходы уже действующий spot-volume ≥1,1x: среди 53 входов выше порога сильных 29/48 (60,4%) и 7 стопов; среди 41 ниже порога сильных 14/41 (34,1%) и 12 стопов. Но блокировка этих 41 всё равно потеряла бы 14 сильных движений.</p>
<p>Остальные одиночные ограничения хуже: убирают от 8 до 31 сильного движения при слабом снижении стопов. Индикаторы 15m–4h в большинстве срезов теряют заметно больше сильных входов, чем удаляют стопов.</p>
<div class="note">Старые входы смешаны с новыми по просьбе. Но по сохранённым значениям только 28 из 96 удовлетворяют всем пяти нынешним входным условиям, поэтому правила всё же не были одинаковыми на всём месяце. Это показано отдельно ниже, а не скрыто.</div>"""),
sec('cohort','Состав и достоверность данных',tbl(['Показатель','Значение'],[['Входов, Dubai-сентябрь','96'],['Полных 72h окон','91 (45 сильных, 46 слабее +10%)'],['Неполные окна','5: ARX, KSM, EPIC, GWEI, JCT'],['Медианный максимум за 72h',f"{d['mfe']['med']:.2f}%".replace('.',',')+" ("+str(d['mfe']['n'])+" окон)"],['Метрики на момент входа (signal_fire)','94/96; у двух входов 31 августа по UTC нет Spot volume и CVD'],['Покрытие','p24h 96, p3h 96, spot volume 94, CVD 94, OI30m 96, Futures Taker 85, funding 96, orderbook 96'],['Индикаторы 15m/30m/1h/4h','пересчитаны по закрытым свечам до входа; у ранних входов — reconstructed, а не наблюдённые в момент входа'],['aVWAP','измерен только у 14–15 входов из 96, поэтому на сентябре не проверяем']])+f"<p>Недельная динамика показывает сильный режимный эффект: доля сильных 72h движений — {WK}. Неделя 4 имеет 5 неполных окон из 10. Разделение на недели — наблюдение, не доказательство работы одного фильтра.</p>"),
sec('gates','Что дали бы нынешние входные условия за месяц',tbl(['Группа по сохранённым значениям','Входов','Сильных 72h / полных','Доля','STOP LOSS','БУ','Неполных'],[[k,v['n'],f"{v['strong']}/{v['complete']}",pc(v['strong_rate']),v['stops'],v['bu'],v['censored']] for k,v in cl.items()])+
 '<h3>Если ограничение не прошло</h3>'+tbl(['Не прошло','Входов','Сильных / полных','Доля','STOP LOSS','БУ'],[[k,v['n'],f"{v['strong']}/{v['complete']}",pc(v['strong_rate']),v['stops'],v['bu']] for k,v in d['fails'].items()])+
 '<h3>Если ограничение прошло</h3>'+tbl(['Прошло','Входов','Сильных / полных','Доля','STOP LOSS','БУ'],[[k,v['n'],f"{v['strong']}/{v['complete']}",pc(v['strong_rate']),v['stops'],v['bu']] for k,v in d['passes'].items()])+
 '<p>Только spot volume заметно разделяет результат. Нарушение p24h (вне 5–15%) даёт 8 стопов из 20 входов; нарушение p3h — 10 стопов из 30; но эти же группы содержат 8 и 15 сильных движений. CVD &lt;2 и отсутствие положительного SNF содержат 0 стопов и 6 и 4 сильных пика — то есть эти два условия на сентябре отсекают качественные входы, а не стопы. Это отдельная проверка, не рекомендация менять правила.</p>'),
sec('bands','Разбивка по диапазонам метрик',band_html+'<p>Лучший по доле сильных диапазон p24h — 10–15%: 23/35 (66%) при 5 стопах. Рост за 3 часа выше 4% даёт 10 стопов из 30, но и 15 сильных. Spot volume ≥2x даёт 13/17 сильных и всего один стоп, поэтому ограничение сверху ≤2x плохо: оно теряет 13 сильных.</p>'),
sec('cuts','Одиночные ограничения и их цена',tbl(CH,cutrows(d['vol']))+'<p>Funding выражен в долях, а не в процентах: 0,0001 = 0,01%. Пороги не оптимизировались; это заранее заданные срезы. Неизвестные значения сохраняются, а не превращаются в провал. Число проверок велико, поэтому небольшая красивая строка не может считаться доказательством.</p>'),
sec('indicators','Индикаторы по закрытым свечам до входа',tbl(CH,cutrows(d['ind']))+'<p>Лучшие случаи: ADX14 ≥20 на 15m/30m/1h убирает 7 входов и 4–6 сильных; ничего не фильтрует значимо. Close location ≥60 на 15m убирает всего 3 из 19 стопов, но теряет 24 сильных. BB percentile ≤50 и ATR percentile ≤75 почти полностью опустошают выборку. aVWAP оставлен для полноты, но измерен лишь у 14–15 входов.</p>'),
sec('ict','ICT/LuxAlgo: пересчёт всех 96 сентябрьских входов',
 '<p>Проверены те же 33 признака на 1H и 4H: <strong>66 структурных срезов</strong>, без подбора новых порогов. '
 'Для 1H достаточно истории у 93/96 входов, для 4H — у 90/96. Остальные значения неизвестны и проходят фильтр. '
 'Каждый срез сохраняет входы с признаком и исключает только входы с достоверно отсутствующим признаком.</p>'
 '<p><strong>Наименее затратный по сильным пикам срез среди убирающих стопы — активный бычий FVG.</strong> '
 'На 4H он исключает 14 входов: 3 стопа, 5 БУ, 4 сильных пика и 1 неполное окно. '
 'Сохранено 41/45 сильных, включая 4 случая с неизвестным признаком. '
 'На 1H исключаются 9 входов: 1 стоп, 4 БУ, те же по числу 4 сильных пика; сохранено 41/45, включая 2 неизвестных. '
 'Неизвестные случаи не являются подтверждением полезности FVG.</p>'
 '<p>Бычий BOS исключает 27–28 сильных пиков ради 12–14 стопов; бычий CHoCH — 25–31 пиков ради 12–14 стопов. '
 'Подтверждённый бычий sweep-reversal теряет 34–39 пиков ради 15–16 стопов. '
 'Demand OB в пределах 1 ATR теряет 38–43 пика ради 17–18 стопов. '
 '<strong>Эти признаки как обязательные условия слишком сильно сокращают сильные входы.</strong></p>'
 + render_tables(ict,tbl)
 + '<h3>Проверка по календарным половинам сентября — Dubai</h3>'
 + tbl(['Период','Входов','Сильных / полных окон','STOP LOSS','БУ','Неполных'],
 [[('1–15 сентября' if k=='sep01_15_dubai' else '16–30 сентября'),v['rows'],
 f"{v['completeStrong10pct']}/{v['completeRows']}",v['exactStopLoss'],v['buStop'],v['censoredRows']]
 for k,v in ict['calendarHalves'].items()])
 + '<p>У 4H FVG в первой половине удаляются 3 стопа и 2 сильных пика, во второй — 0 стопов и 2 сильных пика. '
 'То есть снижение стопов обнаружено только в первой части месяца; во второй контрольная группа имеет всего один стоп. '
 'Это описательное сравнение, не независимая валидация. Готового нового live-фильтра не подтверждено.</p>'
 '<h3>Как выполнен пересчёт</h3><p>350 свечей на запрос, минимум 300 последовательных закрытых свечей до входа. '
 '40 совпадающих слотов из прошлого анализа использованы повторно после проверки ID, времени, символа и исходной цены входа. '
 'Сделано 152 последовательных публичных BingX OHLC-запроса, все успешны. Сырые ответы сохранены отдельно; сборка отчёта не обращается к рынку.</p>'
 '<p>BOS, CHoCH, FVG, sweep, displacement и OB — локальный replay по доступной логике ICT/LuxAlgo, '
 '<strong>не точная копия результатов Pine/TradingView и не сохранённый сигнал на момент входа.</strong> '
 'Premium/discount, canonical dealing range, фактические S/R и retest этим пересчётом не установлены. '
 'Результаты по пикам не доказывают возможность дожить до пика без стопа.</p>'),
sec('paths','Исходы после входа',tbl(['Исход','Входов','С оценкой после закрытия','≥10% после закрытия','Из них новые, без записанного пика ≥10%'],[[k,v['n'],v['eval'],v['hit'],v['new']] for k,v in pcl.items()])+'<p>Все 16 оцениваемых STOP LOSS после закрытия не дали +10% внутри 72 часов. Среди БУ 14 из 35 после закрытия достигли +10%, из них 10 — новые движения (TWT, COTI, XAN, METIS, SOLV, KNC, REZ, ORDI, ATH, NMR). Это показывает потери на сопровождении БУ, а не ошибку фильтра входа. Окно после закрытия ограничено 72 часами от входа.</p>'),
sec('limits','Ограничения',"""<ul><li>ICT/LuxAlgo пересчитан на весь сентябрь, но остаётся source-derived приближением по закрытым свечам, не точным Pine replay.</li><li>Версия правил входа не хранится: сохранённые значения не доказывают, какие именно гейты применялись.</li><li>Сентябрь — один месяц с разными рыночными условиями: стопы сконцентрированы во второй неделе, сильные движения — в третьей.</li><li>72h-пик измерен по 15m high; порядок high/low внутри свечи и исполнимость не известны. Entry basis — original_entry_price, иначе entry_price.</li><li>Неполные окна не считаются неудачами. Реализованный PnL здесь вторичен.</li><li>Ничего в боте, базе, правилах и позициях не менялось.</li></ul>"""),
])
page=f"""<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PLM — весь сентябрь</title><style>*{{box-sizing:border-box}}body{{margin:0;background:#f3f6f7;color:#183340;font:16px/1.65 system-ui,sans-serif}}main{{max-width:1160px;margin:auto;padding:36px 22px 60px}}h1{{font-size:34px;line-height:1.2}}section{{margin-top:24px;padding:24px;background:#fff;border:1px solid #d7e1e5;border-radius:8px}}.note{{background:#e9f3f6;border-left:4px solid #23647a;padding:12px 16px}}.scroll{{overflow-x:auto}}table{{width:100%;border-collapse:collapse;font-size:13px;margin:12px 0}}th,td{{text-align:left;vertical-align:top;padding:9px;border-bottom:1px solid #dbe5e9}}th{{background:#eef4f6}}nav a{{margin-right:14px;color:#14566d}}@media(max-width:640px){{main{{padding:18px 10px}}h1{{font-size:27px}}section{{padding:16px 12px}}}}</style></head><body><main><header><p>PRICE LED MOMENTUM · СЕНТЯБРЬ 2026 · DUBAI</p><h1>PLM за весь сентябрь: пики, ограничения и потери сильных входов</h1><nav>{''.join(f'<a href="#{i}">{t}</a>' for i,t in [('answer','Итог'),('cohort','Данные'),('gates','Условия'),('bands','Диапазоны'),('cuts','Срезы'),('indicators','Индикаторы'),('paths','Исходы'),('limits','Ограничения')])}</nav></header>{body}</main></body></html>"""
